import sys


def count_good_strings(queries):
    # Return a list: for each n in queries, the number of good binary strings of length n modulo 10**9 + 7
    # Write your code here
    return [0] * len(queries)


def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    queries = [int(x) for x in data[1:1 + t]]
    print("\n".join(map(str, count_good_strings(queries))))


if __name__ == "__main__":
    main()
